<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/BranchStock.php';
class BranchDamageReport { private PDO $db;private BranchStock $stock;public function __construct(){$this->db=Database::getConnection();$this->stock=new BranchStock();}
 public function report(int $branchId,int $productId,string $size,string $color,int $quantity,int $userId,?string $note):array{if($quantity<1)return ['success'=>false,'error'=>'Quantity must be at least 1.'];$available=$this->stock->getStock($productId,$size,$color,$branchId);if($available<$quantity)return ['success'=>false,'error'=>'Reported quantity exceeds Branch Inventory stock.'];$s=$this->db->prepare('INSERT INTO branch_damage_reports (branch_id,product_id,variant_size,variant_color,quantity,note,reported_by_user_id) VALUES (:branch_id,:product_id,:size,:color,:quantity,:note,:user_id)');$s->execute(['branch_id'=>$branchId,'product_id'=>$productId,'size'=>$size,'color'=>$color,'quantity'=>$quantity,'note'=>$note?:null,'user_id'=>$userId]);return ['success'=>true];}
 public function pending(int $branchId):array{$s=$this->db->prepare('SELECT r.*,p.name AS product_name,u.name AS reporter_name FROM branch_damage_reports r INNER JOIN products p ON p.id=r.product_id INNER JOIN users u ON u.id=r.reported_by_user_id WHERE r.branch_id=:branch_id AND r.status="reported" ORDER BY r.created_at DESC');$s->execute(['branch_id'=>$branchId]);return $s->fetchAll();}
 public function approve(int $id,int $branchId,int $managerId):array{$this->db->beginTransaction();try{$s=$this->db->prepare('SELECT * FROM branch_damage_reports WHERE id=:id AND branch_id=:branch_id AND status="reported" FOR UPDATE');$s->execute(['id'=>$id,'branch_id'=>$branchId]);$r=$s->fetch();if(!$r)throw new RuntimeException('Damage report was not found or was already reviewed.');$result=$this->stock->markDamaged((int)$r['product_id'],$r['variant_size'],$r['variant_color'],$branchId,(int)$r['quantity'],$managerId,'branch_manager',$r['note']);if(!$result['success'])throw new RuntimeException($result['error']);$this->db->prepare('UPDATE branch_damage_reports SET status="approved",reviewed_by_user_id=:user_id,reviewed_at=NOW() WHERE id=:id')->execute(['user_id'=>$managerId,'id'=>$id]);$this->db->commit();return ['success'=>true];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();return ['success'=>false,'error'=>$e->getMessage()];}}
}
